function applyLanguage(lang){
 const t=Object.assign({},T[lang]||T.en,PROJECT_T[lang]||{},PROJECT_UI_T[lang]||{},CORE_PROJECT_T[lang]||{},CORE_PROJECT_LANG[lang]||{},MORE_PROJECT_T[lang]||{},PROJECT_FIELD_T[lang]||{},HOME_FIX_T[lang]||{},HOME_CONTENT_T[lang]||{});
 document.documentElement.lang=lang;
 document.querySelectorAll("[data-i18n]").forEach(e=>{const v=t[e.dataset.i18n];if(v!==undefined)e.innerHTML=v});
 const s=document.getElementById("languageSelect");if(s)s.value=lang;
 localStorage.setItem("portfolio-language",lang);
}
function detectLanguage(){
 const saved=localStorage.getItem("portfolio-language");
 if(saved&&T[saved])return saved;
 const l=(navigator.language||"en").toLowerCase().split("-")[0];
 return T[l]?l:"en";
}
document.addEventListener("DOMContentLoaded",()=>{
 applyLanguage(detectLanguage());
 const s=document.getElementById("languageSelect");
 if(s)s.addEventListener("change",e=>applyLanguage(e.target.value));

 const progress=document.getElementById("scrollProgress");
 const navLinks=[...document.querySelectorAll('.nav nav a[href^="#"]')];
 const sections=navLinks.map(a=>document.querySelector(a.getAttribute("href"))).filter(Boolean);
 const setProgress=()=>{
   if(!progress)return;
   const max=document.documentElement.scrollHeight-window.innerHeight;
   const value=max>0?(window.scrollY/max)*100:0;
   progress.style.width=Math.min(100,Math.max(0,value))+"%";
 };
 let ticking=false;
 window.addEventListener("scroll",()=>{
   if(ticking)return;
   ticking=true;
   requestAnimationFrame(()=>{setProgress();ticking=false});
 },{passive:true});
 setProgress();

 if("IntersectionObserver" in window && sections.length){
   const observer=new IntersectionObserver(entries=>{
     const visible=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];
     if(!visible)return;
     navLinks.forEach(a=>a.removeAttribute("aria-current"));
     const active=navLinks.find(a=>a.getAttribute("href")===("#"+visible.target.id));
     if(active)active.setAttribute("aria-current","true");
   },{rootMargin:"-24% 0px -58% 0px",threshold:[0,.15,.35,.6]});
   sections.forEach(section=>observer.observe(section));
 }

 document.addEventListener("click",e=>{
   const card=e.target.closest("[data-href]");
   if(card){e.preventDefault();window.location.assign(new URL(card.dataset.href,document.baseURI).href)}
 });
});

